"""Initialize returns list. Each state has four possible actions.

    Args:
        cells ([type]): Array with cells in grid
        actions ([type]): Array with possible actions

    Returns:
        [type]: Rewards dictionary
    """
def returns_lists(cells: Any = 16, actions: Any = 4) -> object {
    def create_array(n: Any, lst: Any) -> object {
        for i in range(n) {
            lst.append(str(i));
        }
        return lst;
    }
    possible_states = [];
    possible_states = create_array(cells, possible_states);
    possible_actions = [];
    possible_actions = create_array(actions, possible_actions);
    returns = {};
    for state in possible_states {
        for action in possible_actions {
            returns[(state + ", " + action)] = [];
        }
    }
    return returns;
}

"""Get string defining the border mode.

    Parameters
    ----------

    pad: tuple[int]
        Zero-padding in x- and y-direction.
    pool_size: list[int]
        Size of kernel.

    Returns
    -------

    padding: str
        Border mode identifier.
    """
def padding_string(pad: Any, pool_size: Any) -> object {
    if (pad == (0, 0)) {
        padding = 'valid';
    } elif (pad == ((pool_size[0] // 2), (pool_size[1] // 2))) {
        padding = 'same';
    } elif (pad == ((pool_size[0] - 1), (pool_size[1] - 1))) {
        padding = 'full';
    } else {
        raise NotImplementedError(
            (
                "Padding {} could not be interpreted as any of the ".format(pad)
                + "supported border modes 'valid', 'same' or 'full'."
            )
        );
    }
    return padding;
}

"""
    split N to M pieces

    see https://stackoverflow.com/a/26554699/9746916
    """
def split_NtoM(N: Any, M: Any, rank: Any) -> object {
    chunk = N // M;
    remainder = N % M;
    if (rank < remainder) {
        start = rank * (chunk + 1);
        stop = start + chunk;
    } else {
        start = (rank * chunk) + remainder;
        stop = start + (chunk - 1);
    }
    return (start, stop);
}

"""
    Converte una stringa in miniscolo con le iniziali in maiuscolo
    :param text: stringa da convertire
    :return: stringa convertita
    """
def capitalize_text(text: Any) -> object {
    array_string = text.lower().split(' ');
    for (i, tmp_name) in enumerate(array_string) {
        array_string[i] = tmp_name.capitalize();
    }
    return ' '.join(array_string);
}

